import{_ as t,o,c as a,a3 as r}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"OpenCode Zen","description":"OpenCode Zen curated model gateway — site entry, free model list, paid notes, and how to fill them in MiniTavern.","frontmatter":{"title":"OpenCode Zen","description":"OpenCode Zen curated model gateway — site entry, free model list, paid notes, and how to fill them in MiniTavern.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"OpenCode Zen · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenCode Zen curated model gateway — site entry, free model list, paid notes, and how to fill them in MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/free-cloud/opencode-zen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/free-cloud/opencode-zen"}]]},"headers":[],"relativePath":"en/free-cloud/opencode-zen.md","filePath":"en/free-cloud/opencode-zen.md","lastUpdated":1787224147000}'),n={name:"en/free-cloud/opencode-zen.md"};function d(i,e,l,s,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h1><p>An <strong>AI gateway</strong> from the <a href="https://opencode.ai/" target="_blank" rel="noreferrer">OpenCode</a> team: curated, tested coding-oriented models, billed per request; plus several <strong>Free</strong> (time/cap-limited) text models. Usable outside OpenCode clients (including MiniTavern). Official docs: <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">Zen (简体)</a>.</p><blockquote><p>Zen is <strong>not</strong> a permanently free-only platform: most flagships are metered and often need billing / top-up; the “free models” below are for trials within caps. Trust the official site for policy.</p></blockquote><h2 id="sites-and-entry-points" tabindex="-1">Sites and entry points <a class="header-anchor" href="#sites-and-entry-points" aria-label="Permalink to &quot;Sites and entry points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Zen intro</td><td><a href="https://opencode.ai/en/zen" target="_blank" rel="noreferrer">opencode.ai/zen</a></td></tr><tr><td>Sign-in / Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>Docs (简体)</td><td><a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">opencode.ai/docs/zh-cn/zen</a></td></tr><tr><td>Model metadata</td><td><code>https://opencode.ai/zen/v1/models</code></td></tr><tr><td>API Base URL (OpenAI-compatible)</td><td><code>https://opencode.ai/zen/v1</code></td></tr></tbody></table><h2 id="how-to-get-free-access" tabindex="-1">How to get free access <a class="header-anchor" href="#how-to-get-free-access" aria-label="Permalink to &quot;How to get free access&quot;">​</a></h2><ol><li>Open <a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> (GitHub / Google) and sign in.</li><li>Create an <strong>API Key</strong> per the console. Official flows often ask for billing info; if you only want Free, still check that auto-recharge is off to avoid surprise charges.</li><li>In MiniTavern pick <strong>Custom (OpenAI)</strong>, Base URL <code>https://opencode.ai/zen/v1</code>, model = a <strong>Free</strong> ID below.</li></ol><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Free path</td><td>Some models priced <strong>Free</strong> (within OpenCode caps); used to gather feedback — may change or retire anytime</td></tr><tr><td>Paid path</td><td>Pay-as-you-go; below $5 balance, default auto-recharge $20 (change or disable in console)</td></tr><tr><td>Card required</td><td>Official “how it works” says add billing info; follow the live console</td></tr><tr><td>Privacy</td><td>Free tiers (e.g. Big Pickle, MiMo Free, Hy3, Nemotron Free, Muse Contributor Free) may use logs to improve models; Nemotron is an NVIDIA trial endpoint — do not send secrets</td></tr></tbody></table><p>Full pricing and deprecations: <a href="https://opencode.ai/docs/zh-cn/zen/#%E5%AE%9A%E4%BB%B7" target="_blank" rel="noreferrer">Zen · Pricing</a>.</p><h2 id="model-list" tabindex="-1">Model list <a class="header-anchor" href="#model-list" aria-label="Permalink to &quot;Model list&quot;">​</a></h2><p>Model IDs are <strong>case-sensitive</strong>. Zen routes vendors differently: <code>/chat/completions</code>, <code>/responses</code>, <code>/messages</code>, or Gemini-specific paths. MiniTavern <strong>Custom (OpenAI)</strong> uses Chat Completions — prefer the <strong>OpenAI-compatible</strong> rows below.</p><p>Full table: <a href="https://opencode.ai/docs/zh-cn/zen/#%E7%AB%AF%E7%82%B9" target="_blank" rel="noreferrer">Zen · Endpoints</a>; or <code>GET https://opencode.ai/zen/v1/models</code>.</p><h3 id="text-·-free-try-these-first" tabindex="-1">Text · Free (try these first) <a class="header-anchor" href="#text-·-free-try-these-first" aria-label="Permalink to &quot;Text · Free (try these first)&quot;">​</a></h3><p>All use <code>…/v1/chat/completions</code> except Muse Contributor Free (Responses).</p><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>mimo-v2.5-free</code></td><td>Xiaomi MiMo V2.5 free</td></tr><tr><td><code>hy3-free</code></td><td>Hy3 Free</td></tr><tr><td><code>big-pickle</code></td><td>Stealth model, free</td></tr><tr><td><code>nemotron-3-ultra-free</code></td><td>NVIDIA Nemotron trial — no secrets</td></tr><tr><td><code>nemotron-3.5-lightning-free</code></td><td>Same</td></tr><tr><td><code>muse-spark-1.2-contributor-free</code></td><td>Contributor free; uses <code>/responses</code> — <strong>MiniTavern Test may not apply</strong>; allows training Meta models on prompts</td></tr></tbody></table><h3 id="text-·-paid-but-openai-compatible-optional" tabindex="-1">Text · Paid but OpenAI-compatible (optional) <a class="header-anchor" href="#text-·-paid-but-openai-compatible-optional" aria-label="Permalink to &quot;Text · Paid but OpenAI-compatible (optional)&quot;">​</a></h3><p>Same Base URL after you top up:</p><table tabindex="0"><thead><tr><th>Model ID</th><th>Notes</th></tr></thead><tbody><tr><td><code>deepseek-v4-flash</code> / <code>deepseek-v4-pro</code></td><td>DeepSeek (Peak / Off-Peak pricing)</td></tr><tr><td><code>glm-5.1</code> / <code>glm-5.2</code> / <code>glm-5</code></td><td>Zhipu GLM</td></tr><tr><td><code>kimi-k2.5</code> / <code>kimi-k2.6</code> / <code>kimi-k2.7-code</code> / <code>kimi-k3</code></td><td>Kimi</td></tr><tr><td><code>minimax-m2.5</code> / <code>minimax-m2.7</code> / <code>minimax-m3</code></td><td>MiniMax</td></tr></tbody></table><h3 id="other-protocols-use-carefully-in-minitavern" tabindex="-1">Other protocols (use carefully in MiniTavern) <a class="header-anchor" href="#other-protocols-use-carefully-in-minitavern" aria-label="Permalink to &quot;Other protocols (use carefully in MiniTavern)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Example IDs</th><th>Endpoint type</th></tr></thead><tbody><tr><td>GPT series</td><td><code>gpt-5.5</code>, <code>gpt-5.4-nano</code>, etc.</td><td><code>/zen/v1/responses</code></td></tr><tr><td>Claude series</td><td><code>claude-sonnet-4-6</code>, <code>claude-haiku-4-5</code>, etc.</td><td><code>/zen/v1/messages</code></td></tr><tr><td>Gemini series</td><td><code>gemini-3-flash</code>, etc.</td><td><code>/zen/v1/models/&lt;id&gt;</code></td></tr></tbody></table><p>These are <strong>not</strong> the same path as MiniTavern’s default OpenAI Chat Completions. For roleplay chat, prefer Free or OpenAI-compatible models above. For Claude, use App <strong>Claude(Anthropic)</strong> with an official Key, or another unified OpenAI gateway such as <a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a>.</p><h3 id="images-video" tabindex="-1">Images / video <a class="header-anchor" href="#images-video" aria-label="Permalink to &quot;Images / video&quot;">​</a></h3><p>Zen’s current catalog is mostly <strong>language models</strong> — <strong>no separate free image / video tier</strong>. For image gen see <a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a>, <a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a>, or <a href="/ultra_guides/en/free-cloud/#free-image-generation">Free image gen</a>.</p><h2 id="how-to-fill-in-minitavern" tabindex="-1">How to fill in MiniTavern <a class="header-anchor" href="#how-to-fill-in-minitavern" aria-label="Permalink to &quot;How to fill in MiniTavern&quot;">​</a></h2><p>General steps: <a href="/ultra_guides/en/manual/model-link">Model link</a>.</p><p>Path: <strong>Settings → Models → Model link → New</strong></p><ol><li>Platform: <strong>Custom (OpenAI)</strong></li><li>Base URL: <code>https://opencode.ai/zen/v1</code></li><li>Paste API Key</li><li>Model ID: <code>mimo-v2.5-free</code> (or another Free / chat-compatible ID)</li><li><strong>Test</strong> → on success, set as default</li></ol><blockquote><p>If Test fails: confirm you did not pick GPT Responses / Claude Messages–only IDs; disable auto-recharge before trying Free; see <a href="/ultra_guides/en/manual/errors">Error codes</a>.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ultra_guides/en/free-cloud/">Free cloud overview</a></li><li><a href="/ultra_guides/en/free-cloud/aihubmix">AIHubMix</a> — one Key for many <code>*-free</code> closed/open models + image gen</li><li><a href="/ultra_guides/en/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/en/manual/model-link">Model link</a></li></ul>',30)])])}const m=t(n,[["render",d]]);export{u as __pageData,m as default};
